import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import DocumentAnalysisFeature, ContentFormat

def extract_receipt_data(receipt_image_path: str) -> dict:
    """
    Extracts merchant, tax, total, and items from a receipt using Azure Document Intelligence.

    Args:
        receipt_image_path: The path to the receipt image file.

    Returns:
        A dictionary containing the extracted information.
    """
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise ValueError("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY environment variables must be set.")

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    with open(receipt_image_path, "rb") as f:
        poller = document_intelligence_client.begin_analyze_document(
            "prebuilt-receipt", analyze_request=f, content_type="application/octet-stream"
        )
        receipt_result = poller.result()

    extracted_data = {
        "merchant_name": None,
        "tax": None,
        "total": None,
        "items": []
    }

    if receipt_result.documents:
        for receipt in receipt_result.documents:
            if receipt.doc_type == "prebuilt:receipt":
                fields = receipt.fields

                # Extract Merchant Name
                if "MerchantName" in fields and fields["MerchantName"].value:
                    extracted_data["merchant_name"] = fields["MerchantName"].value.content

                # Extract Tax
                if "TotalTax" in fields and fields["TotalTax"].value:
                    extracted_data["tax"] = fields["TotalTax"].value.as_float()

                # Extract Total
                if "Total" in fields and fields["Total"].value:
                    extracted_data["total"] = fields["Total"].value.as_float()

                # Extract Items
                if "Items" in fields and fields["Items"].value:
                    for item_field in fields["Items"].value:
                        item_data = {}
                        if "Description" in item_field.value and item_field.value["Description"].value:
                            item_data["description"] = item_field.value["Description"].value.content
                        if "Quantity" in item_field.value and item_field.value["Quantity"].value:
                            item_data["quantity"] = item_field.value["Quantity"].value.as_float()
                        if "Price" in item_field.value and item_field.value["Price"].value:
                            item_data["price"] = item_field.value["Price"].value.as_float()
                        if "TotalPrice" in item_field.value and item_field.value["TotalPrice"].value:
                            item_data["total_price"] = item_field.value["TotalPrice"].value.as_float()
                        extracted_data["items"].append(item_data)
                break # Assuming only one receipt per document for simplicity

    return extracted_data
